// In-browser stand-in for bond.http.server, used with `?mock`. It answers the routes the UI calls from a
// snapshot of a real store (store.json, regenerated by ui/scripts/make_mock.py), following the
// rules in ui/API.md and bond.http.viewer. Development only: nothing outside src/mocks imports it except
// the dynamic imports in `mockBackend` (src/api/client.ts).

import { ApiError } from "../api/client";
import { overlaps } from "../api/locators";
import type {
  Annotations,
  Citation,
  DocumentItem,
  DocumentPage,
  Format,
  Graph,
  GraphEdge,
  GraphNode,
  Kind,
  Locator,
  Neighborhood,
  Overview,
  VersionDetail,
  VersionSummary,
} from "../api/types";
import faxPdfUrl from "./fax.pdf?url";
import store from "./store.json";

type StoredVersion = {
  version: string;
  content_hash: string;
  name: string;
  title: string | null;
  documents: string[];
  format: Format;
  created_at: string;
  content: string | null;
  /** Each claim unit with its text, as bond computes it. */
  units: { locator: Locator; text: string | null }[];
  gaps: Locator[];
};

type Snapshot = { versions: StoredVersion[]; citations: Citation[] };

// JSON imports type string literals as plain `string`; the snapshot is written by make_mock.py
// from a real store, so it is trusted to match the API types.
const snapshot = store as Snapshot;
const { versions, citations } = snapshot;

const byVersion = new Map(versions.map((v) => [v.version, v]));
const citationsOf = (v: string) => citations.filter((c) => c.owner_version === v);

function row(v: string): StoredVersion {
  const r = byVersion.get(v);
  if (!r) throw new ApiError(404, `unknown version ${v}`);
  return r;
}

function summary(v: StoredVersion): VersionSummary {
  const siblings = versions.filter((s) => s.name === v.name);
  const index = siblings.indexOf(v) + 1;
  return {
    version: v.version,
    workspace: "mock",
    content_hash: v.content_hash,
    name: v.name,
    title: v.title,
    documents: v.documents,
    format: v.format,
    created_at: v.created_at,
    version_index: index,
    version_count: siblings.length,
    latest: index === siblings.length,
  };
}

function kindsAt(owned: Citation[], l: Locator): Kind[] {
  return [...new Set(owned.filter((c) => overlaps(c.claim, l)).map((c) => c.kind))].sort();
}

/** The graph over some versions: their nodes, and the citations between them as edges. */
function graphOf(included: StoredVersion[]): Graph {
  const ids = new Set(included.map((v) => v.version));
  const edges = new Map<string, GraphEdge>();
  const nodes = included.map((v): GraphNode => {
    const owned = citationsOf(v.version);
    for (const c of owned) {
      for (const to of new Set(c.supports.map((s) => s.version))) {
        if (to === v.version || !ids.has(to)) continue;
        const id = `${v.version}->${to}`;
        const e = edges.get(id) ?? { id, from: v.version, to, count: 0, kinds: {} };
        e.count++;
        e.kinds[c.kind] = (e.kinds[c.kind] ?? 0) + 1;
        edges.set(id, e);
      }
    }
    return {
      ...summary(v),
      citation_count: owned.length,
      self_citation_count: owned.filter((c) => c.supports.some((s) => s.version === v.version)).length,
      is_source: owned.some((c) => c.kind === "source" && c.claim.type === "version"),
      unreachable: false, // the snapshot is one workspace that links to none
    };
  });
  return { nodes, edges: [...edges.values()] };
}

const graph = (): Graph => graphOf(versions);

/** Breadth first from `center`, through supports and citers, as bond.http.viewer.neighborhood does. */
function neighborhood(center: StoredVersion, depth: number, limit = 200, fanout = 25): Neighborhood {
  const seen = new Set([center.version]);
  let frontier = [center.version];
  let truncated = false;
  for (let d = 0; d < depth; d++) {
    const next: string[] = [];
    for (const v of frontier) {
      const near = [
        ...citationsOf(v).flatMap((c) => c.supports.map((s) => s.version)),
        ...citations.filter((c) => c.supports.some((s) => s.version === v)).map((c) => c.owner_version),
      ];
      let brought = 0;
      for (const n of new Set(near)) {
        if (seen.has(n)) continue;
        if (seen.size >= limit || (v !== center.version && brought >= fanout)) {
          truncated = true;
          break;
        }
        seen.add(n);
        next.push(n);
        brought++;
      }
    }
    frontier = next;
  }
  return { ...graphOf([...seen].map(row)), center: center.version, depth, truncated };
}

/** Documents as the snapshot files them: each name's versions in order, the last its head. */
function documentItems(): DocumentItem[] {
  const names = [...new Set(versions.flatMap((v) => v.documents))].sort();
  return names.flatMap((name) => {
    const held = versions.filter((v) => v.documents.includes(name));
    const [first, head] = [held[0], held.at(-1)];
    if (!first || !head) return []; // every name comes from some version, so never
    const item: DocumentItem = {
      id: `doc_${name}`,
      name,
      title: held.find((v) => v.name === name)?.title ?? null,
      head: head.version,
      format: head.format,
      created_at: first.created_at,
      updated_at: head.created_at,
      version_count: held.length,
    };
    return [item];
  });
}

function documents(params: URLSearchParams): DocumentPage {
  const q = (params.get("q") ?? "").toLowerCase();
  const offset = Number(params.get("offset") ?? 0);
  const limit = Number(params.get("limit") ?? 50);
  const matching = documentItems().filter(
    (d) => d.name.toLowerCase().includes(q) || (d.title ?? "").toLowerCase().includes(q),
  );
  return { total: matching.length, offset, documents: matching.slice(offset, offset + limit) };
}

function overview(): Overview {
  return {
    workspace: { id: "ws_mock", name: "mock", created_at: versions[0]?.created_at ?? "" },
    version_count: versions.length,
    document_count: documentItems().length,
    unreachable_count: 0,
    graph_limit: 300,
  };
}

function detail(v: StoredVersion): VersionDetail {
  return {
    ...summary(v),
    content: v.content,
    siblings: versions.filter((s) => s.name === v.name).map(summary),
  };
}

function annotations(v: StoredVersion): Annotations {
  const owned = citationsOf(v.version);
  return {
    units: v.units.map((u) => ({ locator: u.locator, kinds: kindsAt(owned, u.locator), text: u.text })),
    gaps: v.gaps,
  };
}

function citedBy(v: StoredVersion, l: Locator): Citation[] {
  return citations.filter((c) => c.supports.some((s) => s.version === v.version && overlaps(s.locator, l)));
}

function locatorParam(params: URLSearchParams): Locator {
  const raw = params.get("locator");
  // Trusted like the snapshot: only this UI calls the mock.
  return raw ? (JSON.parse(raw) as Locator) : { type: "version" };
}

const VERSION_ROUTE = /^\/versions\/(?<id>[^/]+)(?<sub>\/citations|\/annotations)?$/;

/** The response body for a GET of `url`, as bond.http.server would send it; throws ApiError like it. */
export function handle(url: string): unknown {
  const { pathname, searchParams } = new URL(url, "http://mock");
  const path = pathname.replace(/^\/api/, "");
  if (path === "/overview") return overview();
  if (path === "/documents") return documents(searchParams);
  if (path === "/graph") return graph();
  if (path === "/neighborhood") {
    return neighborhood(row(searchParams.get("version") ?? ""), Number(searchParams.get("depth") ?? 2));
  }
  if (path === "/cited-by") return citedBy(row(searchParams.get("version") ?? ""), locatorParam(searchParams));
  const route = VERSION_ROUTE.exec(path)?.groups;
  if (route?.id === undefined) throw new ApiError(404, `mock has no route ${path}`);
  const v = row(decodeURIComponent(route.id));
  if (route.sub === "/citations") return citationsOf(v.version);
  if (route.sub === "/annotations") return annotations(v);
  return detail(v);
}

export function blobUrl(v: string): string {
  if (row(v).format !== "pdf") throw new ApiError(400, "the mock only serves PDF blobs");
  return faxPdfUrl;
}
